          ok: false,
          error: { code: "oauth_scope_insufficient", status: 403 },
        });
      }),
  );

  it.effect("invokes OAuth-backed integrations with a rendered bearer token", () =>
    Effect.gen(function* () {
      const server = yield* serveGraphqlTestServer({
        schema: makeGreetingGraphqlSchema(),
