import { Effect, Option, Schema } from "effect";
import { HttpClient, HttpClientRequest } from "effect/unstable/http";

import { GraphqlIntrospectionError } from "./errors";

// ---------------------------------------------------------------------------
// Introspection query — standard GraphQL introspection
// ---------------------------------------------------------------------------

const INTROSPECTION_QUERY = `
  query IntrospectionQuery {
    __schema {
      queryType { name }
      mutationType { name }
      types {
        kind
        name
        description
        fields(includeDeprecated: false) {
          name
          description
          args {
            name
            description
            type {
              ...TypeRef
            }
            defaultValue
          }
          type {
            ...TypeRef
          }
        }
        inputFields {
          name
          description
          type {
            ...TypeRef
          }
          defaultValue
        }
        enumValues(includeDeprecated: false) {
          name
          description
        }
      }
    }
  }

  fragment TypeRef on __Type {
    kind
    name
    ofType {
      kind
      name
      ofType {
        kind
        name
        ofType {
          kind
          name
          ofType {
            kind
            name
            ofType {
              kind
              name
              ofType {
                kind
                name
              }
            }
          }
        }
      }
    }
  }
`;

// ---------------------------------------------------------------------------
// Introspection result types
// ---------------------------------------------------------------------------

const IntrospectionTypeRefLeaf = Schema.Struct({
  kind: Schema.String,
  name: Schema.NullOr(Schema.String),
  ofType: Schema.optional(Schema.Null),
});

const IntrospectionTypeRef5 = Schema.Struct({
  kind: Schema.String,
  name: Schema.NullOr(Schema.String),
  ofType: Schema.optional(Schema.NullOr(IntrospectionTypeRefLeaf)),
});

const IntrospectionTypeRef4 = Schema.Struct({
  kind: Schema.String,
  name: Schema.NullOr(Schema.String),
  ofType: Schema.optional(Schema.NullOr(IntrospectionTypeRef5)),
});

const IntrospectionTypeRef3 = Schema.Struct({
  kind: Schema.String,
  name: Schema.NullOr(Schema.String),
  ofType: Schema.optional(Schema.NullOr(IntrospectionTypeRef4)),
});

const IntrospectionTypeRef2 = Schema.Struct({
  kind: Schema.String,
  name: Schema.NullOr(Schema.String),
  ofType: Schema.optional(Schema.NullOr(IntrospectionTypeRef3)),
});

const IntrospectionTypeRefSchema = Schema.Struct({
  kind: Schema.String,
  name: Schema.NullOr(Schema.String),
  ofType: Schema.optional(Schema.NullOr(IntrospectionTypeRef2)),
});

const IntrospectionInputValueSchema = Schema.Struct({
  name: Schema.String,
  description: Schema.NullOr(Schema.String),
  type: IntrospectionTypeRefSchema,
  defaultValue: Schema.NullOr(Schema.String),
});

const IntrospectionFieldSchema = Schema.Struct({
  name: Schema.String,
  description: Schema.NullOr(Schema.String),
  args: Schema.Array(IntrospectionInputValueSchema),
  type: IntrospectionTypeRefSchema,
});

const IntrospectionTypeSchema = Schema.Struct({
  kind: Schema.String,
  name: Schema.String,
  description: Schema.NullOr(Schema.String),
  fields: Schema.NullOr(Schema.Array(IntrospectionFieldSchema)),
  inputFields: Schema.NullOr(Schema.Array(IntrospectionInputValueSchema)),
  enumValues: Schema.NullOr(
    Schema.Array(
      Schema.Struct({
        name: Schema.String,
        description: Schema.NullOr(Schema.String),
      }),
    ),
  ),
});

const IntrospectionResultSchema = Schema.Struct({
  __schema: Schema.Struct({
    queryType: Schema.NullOr(Schema.Struct({ name: Schema.String })),
    mutationType: Schema.NullOr(Schema.Struct({ name: Schema.String })),
    types: Schema.Array(IntrospectionTypeSchema),
  }),
});

const IntrospectionResponseSchema = Schema.Struct({
  data: Schema.optional(IntrospectionResultSchema),
  errors: Schema.optional(Schema.Array(Schema.Unknown)),
});

const UpstreamErrorResponseSchema = Schema.Struct({
  message: Schema.optional(Schema.String),
  errors: Schema.optional(
    Schema.Array(
      Schema.Struct({
        message: Schema.optional(Schema.String),
      }),
    ),
  ),
});

const IntrospectionJsonSchema = Schema.Union([
  Schema.Struct({ data: IntrospectionResultSchema }),
  IntrospectionResultSchema,
]);
const JsonTextSchema = Schema.fromJsonString(Schema.Unknown);

const decodeUpstreamErrorResponse = Schema.decodeUnknownOption(UpstreamErrorResponseSchema);

export type IntrospectionTypeRef = typeof IntrospectionTypeRefSchema.Type;
export type IntrospectionInputValue = typeof IntrospectionInputValueSchema.Type;
export type IntrospectionField = typeof IntrospectionFieldSchema.Type;
export type IntrospectionEnumValue = NonNullable<
  (typeof IntrospectionTypeSchema.Type)["enumValues"]
>[number];
export type IntrospectionType = typeof IntrospectionTypeSchema.Type;
export type IntrospectionSchema = (typeof IntrospectionResultSchema.Type)["__schema"];
export type IntrospectionResult = typeof IntrospectionResultSchema.Type;

const firstUpstreamErrorMessage = (value: unknown): string | null => {
  const decoded = decodeUpstreamErrorResponse(value);
  return Option.match(decoded, {
    onNone: () => null,
    onSome: (response) => {
      if (response.message) return response.message;
      for (const entry of response.errors ?? []) {
        const message = entry.message;
        if (message) return message;
      }
      return null;
    },
  });
};

const redactUpstreamBody = (body: string): string =>
  body
    .replaceAll(
      /("(?:access_token|refresh_token|id_token|client_secret|token|authorization)"\s*:\s*")[^"]*(")/gi,
      "$1[redacted]$2",
    )
    .replaceAll(
      /((?:access_token|refresh_token|id_token|client_secret|token|authorization)=)[^&\s]*/gi,
      "$1[redacted]",
    )
    .replaceAll(
      /((?:authorization|access-token|refresh-token|id-token|client-secret|token)\s*:\s*)(?:bearer\s+)?[^\s,;]+/gi,
      "$1[redacted]",
    );

const upstreamTextMessage = (body: string): string | null => {
  const text = redactUpstreamBody(body.replaceAll(/\s+/g, " ").trim());
  if (text.length === 0) return null;
  return text.length > 500 ? `${text.slice(0, 500)}...` : text;
};

// ---------------------------------------------------------------------------
// Introspect a GraphQL endpoint
// ---------------------------------------------------------------------------

export const introspect = Effect.fn("GraphQL.introspect")(function* (
  endpoint: string,
  headers?: Record<string, string>,
  queryParams?: Record<string, string>,
) {
  const client = yield* HttpClient.HttpClient;
  const requestEndpoint =
    queryParams && Object.keys(queryParams).length > 0
      ? (() => {
          const url = new URL(endpoint);
          for (const [name, value] of Object.entries(queryParams)) {
            url.searchParams.set(name, value);
          }
          return url.toString();
        })()
      : endpoint;

  let request = HttpClientRequest.post(requestEndpoint).pipe(
    HttpClientRequest.setHeader("Content-Type", "application/json"),
    HttpClientRequest.setHeader("Accept", "application/json"),
    HttpClientRequest.setHeader("User-Agent", "executor-graphql"),
    HttpClientRequest.bodyJsonUnsafe({
      query: INTROSPECTION_QUERY,
    }),
  );

  if (headers) {
    for (const [k, v] of Object.entries(headers)) {
      request = HttpClientRequest.setHeader(request, k, v);
    }
  }

  const response = yield* client.execute(request).pipe(
    Effect.tapCause((cause) => Effect.logError("graphql introspection request failed", cause)),
    Effect.mapError(
      () =>
        new GraphqlIntrospectionError({
          message: "Failed to reach GraphQL endpoint",
          reason: "network",
        }),
    ),
  );

  if (response.status !== 200) {
    const responseText = yield* response.text.pipe(Effect.catch(() => Effect.succeed("")));
    const raw = responseText
      ? yield* Schema.decodeUnknownEffect(JsonTextSchema)(responseText).pipe(
          Effect.catch(() => Effect.succeed(null)),
        )
      : null;
    const upstreamMessage = upstreamTextMessage(
      (raw === null ? null : firstUpstreamErrorMessage(raw)) ?? responseText,
    );
    return yield* new GraphqlIntrospectionError({
      message: upstreamMessage
        ? `Introspection failed with status ${response.status}: ${upstreamMessage}`
        : `Introspection failed with status ${response.status}`,
      status: response.status,
      reason: "http",
      ...(upstreamMessage ? { upstreamMessage } : {}),
    });
  }

  const raw = yield* response.json.pipe(
    Effect.tapCause((cause) => Effect.logError("graphql introspection JSON parse failed", cause)),
    Effect.mapError(
      () =>
        new GraphqlIntrospectionError({
          message: `Failed to parse introspection response as JSON`,
          status: response.status,
          reason: "invalid-json",
        }),
    ),
  );

  const json = yield* Schema.decodeUnknownEffect(IntrospectionResponseSchema)(raw).pipe(
    Effect.mapError(
      () =>
        new GraphqlIntrospectionError({
          message: "Introspection response has an invalid shape",
          status: response.status,
          reason: "invalid-shape",
        }),
    ),
  );

  if (json.errors && Array.isArray(json.errors) && json.errors.length > 0) {
    const upstreamMessage = upstreamTextMessage(firstUpstreamErrorMessage(json) ?? "");
    return yield* new GraphqlIntrospectionError({
      message: upstreamMessage
        ? `Introspection returned ${json.errors.length} error(s): ${upstreamMessage}`
        : `Introspection returned ${json.errors.length} error(s)`,
      status: response.status,
      reason: "graphql-errors",
      ...(upstreamMessage ? { upstreamMessage } : {}),
    });
  }

  if (!json.data?.__schema) {
    return yield* new GraphqlIntrospectionError({
      message: "Introspection response missing __schema",
      status: response.status,
      reason: "missing-schema",
    });
  }

  return json.data;
});

// ---------------------------------------------------------------------------
// Parse an introspection result from a JSON string (for offline/text input)
// ---------------------------------------------------------------------------

export const parseIntrospectionJson = (
  text: string,
): Effect.Effect<IntrospectionResult, GraphqlIntrospectionError> =>
  Schema.decodeUnknownEffect(Schema.fromJsonString(IntrospectionJsonSchema))(text).pipe(
    Effect.map((parsed) => ("data" in parsed ? parsed.data : parsed)),
    Effect.mapError(
      () =>
        new GraphqlIntrospectionError({
          message: "Failed to parse introspection JSON",
        }),
    ),
  );

import { Effect, Layer, Option } from "effect";
import { HttpClient, HttpClientRequest } from "effect/unstable/http";

import { GraphqlInvocationError } from "./errors";
import { type OperationBinding, InvocationResult } from "./types";

const endpointWithQueryParams = (endpoint: string, queryParams: Record<string, string>): string => {
  if (Object.keys(queryParams).length === 0) return endpoint;
  const url = new URL(endpoint);
  for (const [name, value] of Object.entries(queryParams)) {
    url.searchParams.set(name, value);
  }
  return url.toString();
};

export const endpointForTelemetry = (endpoint: string): string => {
  if (!URL.canParse(endpoint)) return endpoint;
  const url = new URL(endpoint);
  url.search = "";
  url.hash = "";
  return url.toString();
};

// Below Cloudflare's approximate 125-second subrequest limit while preserving
// slow upstream requests that Executor's HTTP transports support.
export const GRAPHQL_INVOCATION_TIMEOUT_MS = 110_000;

export interface GraphqlInvokeOptions {
  readonly timeoutMs?: number;
}

const formatTimeout = (timeoutMs: number): string =>
  timeoutMs % 1_000 === 0 ? `${timeoutMs / 1_000}s` : `${timeoutMs}ms`;

const invocationTimeoutMessage = (timeoutMs: number): string =>
  `GraphQL upstream did not complete within ${formatTimeout(timeoutMs)}. The request was aborted. Retry the operation or verify that the endpoint is responsive.`;

/** The operation string to send for a call. A caller-supplied `select` overrides
 *  the default scalar-leaf selection: it is spliced into the field's selection
 *  set (`field { <select> }`) so nested/list data can be requested per call. Falls
 *  back to the stored default operation when `select` is absent or the binding
 *  predates the prefix/suffix split. `select` is a control input, never a GraphQL
 *  variable. Shared with plugin.invokeTool so the validated string matches the
 *  sent string exactly. */
export const effectiveOperationString = (
  operation: OperationBinding,
  args: Record<string, unknown>,
): string => {
  const customSelect = typeof args.select === "string" ? args.select.trim() : "";
  return customSelect.length > 0 &&
    operation.operationPrefix != null &&
    operation.operationSuffix != null
    ? `${operation.operationPrefix} { ${customSelect} }${operation.operationSuffix}`
    : operation.operationString;
};

// ---------------------------------------------------------------------------
// Response helpers
// ---------------------------------------------------------------------------

const isJsonContentType = (ct: string | null | undefined): boolean => {
  if (!ct) return false;
  const normalized = ct.split(";")[0]?.trim().toLowerCase() ?? "";
  return (
    normalized === "application/json" || normalized.includes("+json") || normalized.includes("json")
  );
};

// ---------------------------------------------------------------------------
// Public API — execute a GraphQL operation
// ---------------------------------------------------------------------------

export const invoke = Effect.fn("GraphQL.invoke")(function* (
  operation: OperationBinding,
  args: Record<string, unknown>,
  endpoint: string,
  resolvedHeaders: Record<string, string>,
  resolvedQueryParams: Record<string, string> = {},
  options: GraphqlInvokeOptions = {},
) {
  const client = yield* HttpClient.HttpClient;
  const timeoutMs = options.timeoutMs ?? GRAPHQL_INVOCATION_TIMEOUT_MS;
  const requestEndpoint = endpointWithQueryParams(endpoint, resolvedQueryParams);
  const telemetryEndpoint = endpointForTelemetry(endpoint);

  yield* Effect.annotateCurrentSpan({
    "http.method": "POST",
    "http.url": telemetryEndpoint,
    "plugin.graphql.endpoint": telemetryEndpoint,
    "plugin.graphql.operation_kind": operation.kind,
    "plugin.graphql.field_name": operation.fieldName,
    "plugin.graphql.headers.resolved_count": Object.keys(resolvedHeaders).length,
    "plugin.graphql.query_params.resolved_count": Object.keys(resolvedQueryParams).length,
  });

  // Build the GraphQL request body
  const variables: Record<string, unknown> = {};
  for (const varName of operation.variableNames) {
    if (args[varName] !== undefined) {
      variables[varName] = args[varName];
    }
  }

  // Also pick up any variables from a "variables" container
  if (typeof args.variables === "object" && args.variables !== null) {
    Object.assign(variables, args.variables);
  }

  // `select` (a control input, not a GraphQL variable) is applied here and never
  // enters `variables`. plugin.invokeTool validates this same string before we
  // reach the network.
  const operationString = effectiveOperationString(operation, args);

  let request = HttpClientRequest.post(requestEndpoint).pipe(
    HttpClientRequest.setHeader("Content-Type", "application/json"),
    HttpClientRequest.bodyJsonUnsafe({
      query: operationString,
      variables: Object.keys(variables).length > 0 ? variables : undefined,
    }),
  );

  for (const [name, value] of Object.entries(resolvedHeaders)) {
    request = HttpClientRequest.setHeader(request, name, value);
  }

  return yield* Effect.gen(function* () {
    const response = yield* client.execute(request).pipe(
      Effect.mapError(
        (err) =>
          new GraphqlInvocationError({
            message: "GraphQL request failed",
            statusCode: Option.none(),
            cause: err,
          }),
      ),
    );

    const status = response.status;
    const contentType = response.headers["content-type"] ?? null;

    const body: unknown = isJsonContentType(contentType)
      ? yield* response.json.pipe(Effect.catch(() => response.text))
      : yield* response.text;

    // GraphQL responses are always 200 with { data, errors }
    const gqlBody = body as { data?: unknown; errors?: unknown[] } | null;
    const hasErrors = Array.isArray(gqlBody?.errors) && gqlBody.errors.length > 0;

    yield* Effect.annotateCurrentSpan({
      "http.status_code": status,
      "plugin.graphql.has_errors": hasErrors,
      "plugin.graphql.error_count": hasErrors ? gqlBody!.errors!.length : 0,
    });

    return InvocationResult.make({
      status,
      data: gqlBody?.data ?? null,
      errors: hasErrors ? gqlBody!.errors : null,
      body,
      headers: { ...response.headers },
    });
  }).pipe(
    Effect.timeoutOrElse({
      duration: timeoutMs,
      orElse: () =>
        Effect.fail(
          new GraphqlInvocationError({
            message: invocationTimeoutMessage(timeoutMs),
            statusCode: Option.none(),
            reason: "invocation_timeout",
            timeoutMs,
          }),
        ),
    }),
  );
});

// ---------------------------------------------------------------------------
// Invoke a GraphQL operation with a provided HttpClient layer
// ---------------------------------------------------------------------------

export const invokeWithLayer = (
  operation: OperationBinding,
  args: Record<string, unknown>,
  endpoint: string,
  resolvedHeaders: Record<string, string>,
  resolvedQueryParams: Record<string, string>,
  httpClientLayer: Layer.Layer<HttpClient.HttpClient>,
  options: GraphqlInvokeOptions = {},
) =>
  invoke(operation, args, endpoint, resolvedHeaders, resolvedQueryParams, options).pipe(
    Effect.provide(httpClientLayer),
    Effect.withSpan("plugin.graphql.invoke", {
      attributes: {
        "plugin.graphql.endpoint": endpointForTelemetry(endpoint),
        "plugin.graphql.operation_kind": operation.kind,
        "plugin.graphql.field_name": operation.fieldName,
      },
    }),
  );

